import {ADDITIONAL_ACTIVITIES,normalizeAdditional,markAdditional} from './quiz-additional-model.mjs';
import {questionImage,quizFiles,QUIZ_FILE_EXTENSIONS} from './quiz-media.mjs';
const fail=message=>Object.assign(Error(message),{status:400});
export const QUESTION_LABELS={choice:'Multiple choice (MCQ)',checkboxes:'Checkboxes / multiple answers',dropdown:'Dropdown',truefalse:'True / false',short:'Short answer',paragraph:'Written response',math:'Maths / formula answer',missing:'Missing words',dragwords:'Drag words into gaps',matching:'Matching / connectors',ranking:'Ranking / drag-and-drop order',grid:'Multiple-choice grid',checkboxgrid:'Checkbox grid',likert:'Likert matrix',scale:'Linear scale',rating:'Rating',nps:'Net Promoter Score (0–10)',date:'Date',datetime:'Date & time',time:'Time',duration:'Duration',file:'File upload response',section:'Section / instructions',image:'Image / diagram block',video:'Video resource',external:'Connected activity / external tool'};
Object.assign(QUESTION_LABELS,Object.fromEntries(Object.entries(ADDITIONAL_ACTIVITIES).map(([k,v])=>[k,v[0]])));
export const QUESTION_TYPES=Object.keys(QUESTION_LABELS);
export const DISPLAY_TYPES=['section','image','video'];
export const SINGLE_TYPES=['choice','dropdown','truefalse'];
export const MATRIX_TYPES=['grid','checkboxgrid','likert'];
const clean=(v,n)=>String(v??'').trim().slice(0,n);
const normalized=s=>String(s).normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('en');
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const fraction=(n,d,points)=>Math.round(n/d*points*100)/100;
function lines(value,min=1,max=12){if(!Array.isArray(value)||value.length<min||value.length>max||value.some(x=>typeof x!=='string'||!x.trim()||x.length>500)||new Set(value.map(normalized)).size!==value.length)throw fail('Enter '+min+'–'+max+' different, non-empty items.');return value.map(x=>x.trim());}
function indices(value,size,multiple=false,optional=false){if(optional&&(value===null||value===undefined||value===''))return undefined;const values=multiple?value:[value];if(!Array.isArray(values)||!values.length||values.some(v=>!Number.isInteger(v)||v<0||v>=size)||new Set(values).size!==values.length)throw fail('Choose a valid answer key.');return multiple?values.slice().sort((a,b)=>a-b):values[0];}
export function numericAnswer(value){if(typeof value==='number')return Number.isFinite(value)?value:null;if(typeof value!=='string')return null;let s=value.trim().replaceAll('−','-');s=s.replace(/^\\frac\{([+-]?[\d.]+)\}\{([+-]?[\d.]+)\}$/,'$1/$2');if(['pi','π','\\pi'].includes(s))return Math.PI;const root=s.match(/^(?:sqrt\(([^)]+)\)|\\sqrt\{([^}]+)\})$/);if(root){const n=numericAnswer(root[1]||root[2]);return n!==null&&n>=0?Math.sqrt(n):null;}const power=s.match(/^([+-]?[\d.]+)\s*\^\s*\{?([+-]?[\d.]+)\}?$/);if(power){const n=Number(power[1])**Number(power[2]);return Number.isFinite(n)?n:null;}if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(s)){const n=Number(s);return Number.isFinite(n)?n:null;}if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)\s*\/\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)){const [a,b]=s.split('/').map(Number);return b&&Number.isFinite(a/b)?a/b:null;}return null;}
export function normalizeQuestions(source){
 if(!Array.isArray(source)||!source.length||source.length>40)throw fail('Add between 1 and 40 questions or content blocks.');
 const result=source.map((q,i)=>{const type=q.type,prompt=clean(q.prompt,2000),display=DISPLAY_TYPES.includes(type),points=display?0:Number(q.points);if(!QUESTION_TYPES.includes(type)||!prompt||!Number.isFinite(points)||points<0||points>100)throw fail('Each question needs a prompt, a type and 0–100 points.');const r={id:'q'+(i+1),objective:clean(q.objective,160),type,prompt,points,required:display?false:q.required!==false,description:clean(q.description,2000),formula:clean(q.formula,2000)};
  if(q.image)r.image=questionImage(q.image);if(type==='image'&&!r.image)throw fail('Upload an image for the image block.');
  if([...SINGLE_TYPES,'checkboxes'].includes(type)){r.options=type==='truefalse'?['True','False']:lines(q.options,2,20);r.correct=indices(q.correct,r.options.length,type==='checkboxes',points===0);if(q.optionImages){r.optionImages={};for(const [key,img]of Object.entries(q.optionImages)){if(!/^\d+$/.test(key)||Number(key)>=r.options.length)throw fail('An option image has no matching choice.');if(img)r.optionImages[key]=questionImage(img);}}}
  if(type==='paragraph')r.guidance=clean(q.guidance,5000);
  if(['short','math'].includes(type))r.acceptedAnswers=Array.isArray(q.acceptedAnswers)?q.acceptedAnswers.map(x=>clean(x,500)).filter(Boolean).slice(0,20):[];
  if(type==='math'){r.mathMode=q.mathMode==='numeric'?'numeric':'expression';if(r.mathMode==='numeric'){r.numericKey=numericAnswer(q.numericKey);if(points>0&&r.numericKey===null)throw fail('Enter the numerical answer or fraction for the maths answer key.');r.tolerance=Number(q.tolerance??0);if(!Number.isFinite(r.tolerance)||r.tolerance<0||r.tolerance>1000000)throw fail('Choose a non-negative numeric tolerance.');}}
  if(['missing','dragwords'].includes(type)){const raw=clean(q.passage,10000),matches=[...raw.matchAll(/\[\[([^\[\]]+)\]\]/g)];if(!matches.length||matches.length>20)throw fail('Write 1–20 gaps using [[answer]] or [[answer|alternative]].');r.blankAnswers=matches.map(m=>m[1].split('|').map(x=>clean(x,200)).filter(Boolean));if(r.blankAnswers.some(x=>!x.length))throw fail('Every gap needs an answer.');let n=0;r.passage=raw.replace(/\[\[([^\[\]]+)\]\]/g,()=>`[[${++n}]]`);if(type==='dragwords'){r.wordBank=[...new Set([...r.blankAnswers.map(x=>x[0]),...(Array.isArray(q.wordBank)?q.wordBank.map(x=>clean(x,200)).filter(Boolean):[])])].sort((a,b)=>a.localeCompare(b));if(r.wordBank.length>40)throw fail('Use up to 40 words in a word bank.');}}
  if(type==='ranking'){r.options=lines(q.options,2,12).slice().sort((a,b)=>a.localeCompare(b));r.correct=q.options.map(x=>r.options.indexOf(x.trim()));}
  if(type==='matching'){if(!Array.isArray(q.pairs)||q.pairs.length<2||q.pairs.length>12)throw fail('Add 2–12 matching pairs.');r.rows=lines(q.pairs.map(p=>p.left),2,12);r.options=lines(q.pairs.map(p=>p.right),2,12).sort((a,b)=>a.localeCompare(b));r.correct=q.pairs.map(p=>r.options.indexOf(p.right.trim()));r.uniqueColumns=true;}
  if(MATRIX_TYPES.includes(type)){r.rows=lines(q.rows,1,12);r.options=lines(q.options,2,12);r.uniqueColumns=!!q.uniqueColumns;r.correct=Array.isArray(q.correct)&&q.correct.length?q.correct.map(v=>indices(v,r.options.length,type==='checkboxgrid')):null;if(r.correct&&r.correct.length!==r.rows.length)throw fail('Provide a grid answer for every row or leave the whole key blank for teacher marking.');}
  if(['scale','rating','nps'].includes(type)){r.minimum=type==='nps'?0:Number(q.minimum??(type==='rating'?1:0));r.maximum=type==='nps'?10:Number(q.maximum??5);if(!Number.isInteger(r.minimum)||!Number.isInteger(r.maximum)||r.minimum<0||r.minimum>1||r.maximum<2||r.maximum>10||r.maximum<=r.minimum)throw fail('Use a scale starting at 0 or 1 and ending from 2 to 10.');r.lowLabel=clean(q.lowLabel,100);r.highLabel=clean(q.highLabel,100);r.ratingIcon=['star','heart','thumb'].includes(q.ratingIcon)?q.ratingIcon:'star';if(q.correct!==undefined&&q.correct!==''&&q.correct!==null){r.correct=Number(q.correct);if(!Number.isInteger(r.correct)||r.correct<r.minimum||r.correct>r.maximum)throw fail('The scale answer key is outside the scale.');}}
  if(['date','datetime','time','duration'].includes(type))r.acceptedAnswers=Array.isArray(q.acceptedAnswers)?q.acceptedAnswers.map(x=>clean(x,50)).filter(Boolean).slice(0,10):[];
  if(type==='file'){r.allowedExtensions=Array.isArray(q.allowedExtensions)&&q.allowedExtensions.length?q.allowedExtensions.filter(x=>QUIZ_FILE_EXTENSIONS.includes(x)):['pdf','docx','png','jpg'];r.maxFiles=Number(q.maxFiles??1);if(!r.allowedExtensions.length||!Number.isInteger(r.maxFiles)||r.maxFiles<1||r.maxFiles>3)throw fail('Choose supported upload types and a limit of 1–3 files.');}
  if(['video','external'].includes(type)){let u;try{u=new URL(q.resource);}catch{throw fail('Enter a complete HTTPS resource URL.');}if(u.protocol!=='https:'||u.username||u.password)throw fail('Use HTTPS links without embedded credentials.');r.resource=u.href;r.provider=clean(q.provider,80)||'Web resource';}
  if(ADDITIONAL_ACTIVITIES[type])normalizeAdditional(q,r);
  if(q.feedback)r.feedback={correct:clean(q.feedback.correct,2000),incorrect:clean(q.feedback.incorrect,2000)};
  return r;
 });if(JSON.stringify(result).length>11000000)throw fail('This quiz has too many image attachments. Keep total images below 8 MB.');return result;
}
export function studentQuestions(questions){return questions.map(({correct,acceptedAnswers,blankAnswers,numericKey,tolerance,feedback,guidance,...safe})=>safe);}
export function markQuiz(questions,input,{draft=false}={}){
 if(!input||typeof input!=='object'||Array.isArray(input))throw fail('Enter your quiz answers.');if(Object.keys(input).some(id=>!questions.some(q=>q.id===id)))throw fail('An answer does not belong to this quiz.');const answers={},autoMarks={};
 for(const q of questions){let v=input[q.id],empty=false,score=null;if(DISPLAY_TYPES.includes(q.type)){answers[q.id]=null;autoMarks[q.id]=0;continue;}
  if(ADDITIONAL_ACTIVITIES[q.type]){const result=markAdditional(q,v,{draft});v=result.value;score=result.score;empty=result.empty;}
  else if(SINGLE_TYPES.includes(q.type)){empty=v===''||v===undefined||v===null;v=empty?null:indices(v,q.options.length);if(!empty&&q.correct!==undefined)score=v===q.correct?q.points:0;}
  else if(q.type==='checkboxes'){v=v??[];empty=Array.isArray(v)&&!v.length;if(!empty)v=indices(v,q.options.length,true);if(!Array.isArray(v))throw fail('Choose valid options.');if(!empty&&q.correct!==undefined)score=same(v,q.correct)?q.points:0;}
  else if(['missing','dragwords'].includes(q.type)){v=v??[];if(!Array.isArray(v)||v.length>q.blankAnswers.length||v.some(x=>typeof x!=='string'||x.length>500))throw fail('Enter valid missing-word answers.');v=Array.from({length:q.blankAnswers.length},(_,i)=>clean(v[i],500));empty=v.some(x=>!x);score=fraction(v.filter((x,i)=>q.blankAnswers[i].some(a=>normalized(a)===normalized(x))).length,v.length,q.points);}
  else if(q.type==='ranking'){v=v??[];empty=!v.length;if(!Array.isArray(v)||(!empty&&(v.length!==q.options.length||new Set(v).size!==v.length||v.some(x=>!Number.isInteger(x)||x<0||x>=q.options.length))))throw fail('Rank each item exactly once.');if(!empty)score=same(v,q.correct)?q.points:0;}
  else if(q.type==='matching'||MATRIX_TYPES.includes(q.type)){v=v??[];if(!Array.isArray(v)||v.length>q.rows.length)throw fail('Enter valid row answers.');v=Array.from({length:q.rows.length},(_,i)=>{const a=v[i];if(q.type==='checkboxgrid')return !a?.length?[]:indices(a,q.options.length,true);return a===undefined||a===null||a===''?null:indices(a,q.options.length);});empty=v.some(x=>Array.isArray(x)?!x.length:x===null);if(q.uniqueColumns){const cells=v.flat().filter(x=>x!==null);if(new Set(cells).size!==cells.length)throw fail('Use each column or matching target at most once.');}if(q.correct)score=fraction(v.filter((x,i)=>same(x,q.correct[i])).length,q.rows.length,q.points);}
  else if(['scale','rating','nps'].includes(q.type)){empty=v===undefined||v===null||v==='';if(empty)v=null;else{if(!Number.isInteger(v)||v<q.minimum||v>q.maximum)throw fail('Choose a value within the scale.');if(q.correct!==undefined)score=v===q.correct?q.points:0;}}
  else if(q.type==='file'){v=quizFiles(v??[],{maxFiles:q.maxFiles,allowed:q.allowedExtensions});empty=!v.length;}
  else{if(v!==undefined&&typeof v!=='string')throw fail('Enter a valid text answer.');v=clean(v,q.type==='paragraph'?10000:2000);empty=!v;
   if(v&&['date','datetime'].includes(q.type)){const m=v.match(/^(\d{4}-\d{2}-\d{2})(?:T([01]\d|2[0-3]):([0-5]\d))?$/);if(!m||new Date(m[1]+'T00:00:00Z').toISOString().slice(0,10)!==m[1]||q.type==='datetime'&&!m[2])throw fail('Enter a valid date and time.');}
   if(v&&q.type==='time'&&!/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(v))throw fail('Enter a valid time.');if(v&&q.type==='duration'&&!/^\d{1,4}:[0-5]\d:[0-5]\d$/.test(v))throw fail('Use hours:minutes:seconds for the duration.');
   if(!empty&&q.type==='math'&&q.mathMode==='numeric'){const n=numericAnswer(v);score=n!==null&&Math.abs(n-q.numericKey)<=q.tolerance?q.points:0;}else if(!empty&&q.acceptedAnswers?.length)score=q.acceptedAnswers.some(a=>normalized(a)===normalized(v))?q.points:0;
  }
  if(!draft&&q.required&&empty)throw fail('Answer required question '+q.id.replace('q','')+' before turning in.');answers[q.id]=v;autoMarks[q.id]=q.points===0?0:empty?0:score;
 }if(JSON.stringify(answers).length>11000000)throw fail('Keep total uploaded responses below 8 MB.');return{answers,autoMarks,autoTotal:Object.values(autoMarks).filter(v=>v!==null).reduce((a,b)=>a+b,0),needsReview:Object.values(autoMarks).some(v=>v===null)};
}
export function reviewedMarks(questions,input){if(!input||typeof input!=='object'||Array.isArray(input))throw fail('Mark each question before returning this quiz.');const marks={};for(const q of questions){const value=q.points===0?0:input[q.id];if(typeof value!=='number'||!Number.isFinite(value)||value<0||value>q.points)throw fail('Enter a mark from 0 to '+q.points+' for question '+q.id.replace('q','')+'.');marks[q.id]=value;}return{questionMarks:marks,mark:Object.values(marks).reduce((a,b)=>a+b,0)};}
